content.text:
// Issue #320 e2e: inbound hub/DAP/bridge mail is VISIBLE in the chat — the
// host announces the attributed user message ("[from <peer>] <text>") at
// ARRIVAL (bubble + event, before the assistant reply), queues mid-run mail
// behind a pending status until the step boundary delivers it, and keeps
// AC18 dedupe (one bubble per delivery).
//
// Drives faAgent.pushMail directly — the host intake seam the bug pinned —
// on the deterministic fake provider: no hub, no LLM. The default PR leg
// runs the legacy panel (no app bundle); with --with-app builds the v2 app
// branch renders instead (covered at unit level by flutter_app relay tests).
import {
  appBundlePresent,
  awaitPanelSettled,
  expect,
  skipWithoutChrome,
  test,
  type FaEvent,
} from './helpers';

skipWithoutChrome();

const MAIL = 'hallo from the hub';
const MAIL_ROW = '[from peer-1] hallo from the hub';

/** User rows carry the host's per-turn `[context] …` header when the turn
 * injected tool-tab context — both surfaces strip it for display; the spec
 * mirrors that before matching. */
function clean(t: string | undefined): string {
  const raw = t ?? '';
  const at = raw.indexOf('\n');
  return raw.startsWith('[context] ') && at > 0 ? raw.slice(at + 1) : raw;
}


test.describe('inbound mail visibility (#320)', () => {
  skipWithoutChrome();

  test('AC1/E4/AC6: idle mail renders the attributed user bubble at arrival '
      + 'before the reply, exactly once — duplicates stay deduped', async ({
    fa,
  }) => {
    // The bubbles under test are the legacy fallback transcript (.bubble.user,
    // #transcript). With an app bundle the panel redirects to the Flutter app
    // before that DOM can ever render — the selectors never resolve there
    // (gh-1521). Same convention as panel-focus/paste; the app branch's mail
    // rendering (incl. the AC18 dedup-by-message-id invariant) is covered at
    // unit level by flutter_app/test/relay_agent_service_test.dart _mailTests.
    test.skip(
      appBundlePresent,
      'legacy transcript only — the app build redirects the panel to app/',
    );
    await fa.swEval((mode) => {
      const sw = globalThis as unknown as {
        faAgent: { boot(c: unknown): Promise<unknown> };
      };
      return sw.faAgent.boot({ approvalMode: mode });
    }, 'unattended');
    await expect
      .poll(() =>
        fa.swEval(() => {
          const sw = globalThis as unknown as {
            faAgent: { getState(): { booted: boolean } };
          };
          return sw.faAgent.getState().booted;
        }),
      )
      .toBe(true);
    // The panel's push-port binds to the SW instance alive at page load;
    // booting the agent may have revived the SW since, orphaning it.
    // Reload so the panel subscribes on the live instance (real users
    // open the panel after boot all the time).
    await fa.panel.reload();
    await awaitPanelSettled(fa.panel);
    // NOTE: no fa.collectEvents() here — the seam's onEvent is a SINGLE
    // callback (last writer wins); installing the spec collector would
    // overwrite sw/main.js's panel pusher and blind the very DOM under
    // test. Event-level assertions live in the test below.
    await fa.swEval((payload: [string, string]) => {
      const sw = globalThis as unknown as {
        faAgent: { pushMail(from: string, text: string): void };
      };
      sw.faAgent.pushMail(payload[0], payload[1]);
    }, ['peer-1', MAIL]);

    // AC1: the attributed user bubble renders in the legacy transcript,
    // as the FIRST bubble — before the assistant reply.
    const userBubble = fa.panel.locator('.bubble.user', { hasText: MAIL_ROW });
    await expect(userBubble).toHaveCount(1);
    await expect(fa.panel.locator('#transcript > div').first()).toHaveClass(
      /bubble user/,
    );
    await expect(fa.panel.locator('.bubble.assistant')).toHaveCount(1);

    // AC18 dedupe: the same delivery again (at-least-once hub) — no
    // second bubble, no restarted turn.
    await fa.swEval((payload: [string, string]) => {
      const sw = globalThis as unknown as {
        faAgent: { pushMail(from: string, text: string): void };
      };
      sw.faAgent.pushMail(payload[0], payload[1]);
    }, ['peer-1', MAIL]);
    await fa.panel.waitForTimeout(1500);
    await expect(
      fa.panel.locator('.bubble.user', { hasText: MAIL_ROW }),
    ).toHaveCount(1);
    const running = await fa.swEval(() => {
      const sw = globalThis as unknown as {
        faAgent: { getState(): { running: boolean } };
      };
      return sw.faAgent.getState().running;
    });
    expect(running).toBe(false);
  });

  test('AC3: mid-run mail queues behind a pending indicator and renders '
      + 'exactly once at the boundary', async ({ fa }) => {
    await fa.swEval((mode) => {
      const sw = globalThis as unknown as {
        faAgent: { boot(c: unknown): Promise<unknown> };
      };
      return sw.faAgent.boot({ approvalMode: mode });
    }, 'always-ask');
    await expect
      .poll(() =>
        fa.swEval(() => {
          const sw = globalThis as unknown as {
            faAgent: { getState(): { booted: boolean } };
          };
          return sw.faAgent.getState().booted;
        }),
      )
      .toBe(true);
    await fa.collectEvents();

    // Open a deterministic mid-run window: a navigate prompt parks the turn
    // on the always-ask approval gate (fake provider scripts the tool call).
    await fa.sendUser(`navigate ${fa.fixture.url}`);
    const approval = await fa.waitEvent((e) => e.type === 'approval_request');

    // Mail lands mid-run: queued, announced with sender + count.
    const before = await fa.eventCount();
    await fa.swEval((payload: [string, string]) => {
      const sw = globalThis as unknown as {
        faAgent: { pushMail(from: string, text: string): void };
      };
      sw.faAgent.pushMail(payload[0], payload[1]);
    }, ['peer-2', 'queued mid-run hello']);
    await fa.waitEvent(
      (e) =>
        e.type === 'status' &&
        (e.mail as { pending?: number } | undefined)?.pending === 1,
      45_000,
      before - 1,
    );

    // The boundary: approval resolves, the turn drains the mail as steering
    // and the delivered bubble renders exactly once.
    await fa.decide(approval.id!, true);
    await expect.poll(async () => {
      const events = await fa.events();
      return events.filter(
        (e) =>
          e.type === 'message_done' &&
          e.role === 'user' &&
          clean(e.text) === '[from peer-2] queued mid-run hello',
      ).length;
    }).toBe(1);

    // Delivered → the pending indicator is gone from the host state.
    await expect.poll(() =>
      fa.swEval(() => {
        const sw = globalThis as unknown as {
          faAgent: { getState(): { running: boolean; mail?: unknown } };
        };
        const state = sw.faAgent.getState();
        return state.running || state.mail != null;
      }),
    ).toBe(false);
  });
});

// E2E-steer (issue #314): steering a RUNNING stream must be delivered at
// the next step boundary — never kill the stream ("request aborted").
// Drives the REAL compiled sw/agent.js in headless Chrome: a local
// OpenAI-compatible SSE server streams a reply slowly, the test steers
// mid-stream through the same sendUser seam the panel composer uses, and
// the run must finish: first reply completes naturally, the steering
// becomes the next user step, its reply follows — with NO aborted error
// anywhere on the event stream.
import http from 'node:http';
import { expect, FaHarness, skipWithoutChrome, test } from './helpers';
import { appBundlePresent } from './helpers';

/** One slow OpenAI chat-completions SSE response: 8 deltas, 250ms apart. */
async function startSlowSseServer(): Promise<{
  server: http.Server;
  url: string;
}> {
  const server = http.createServer((req, res) => {
    if (req.method === 'POST' && req.url?.endsWith('/chat/completions')) {
      req.resume();
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      let i = 0;
      const chunk = (delta: Record<string, unknown>, finish: string | null) =>
        `data: ${JSON.stringify({
          id: 'chatcmpl-slow',
          object: 'chat.completion.chunk',
          created: 1,
          model: 'slow',
          choices: [{ index: 0, delta, finish_reason: finish }],
        })}\n\n`;
      const timer = setInterval(() => {
        i++;
        res.write(chunk({ content: `d${i} ` }, null));
        if (i >= 8) {
          clearInterval(timer);
          res.write(chunk({}, 'stop'));
          res.write('data: [DONE]\n\n');
          res.end();
        }
      }, 250);
      res.on('close', () => clearInterval(timer));
      return;
    }
    res.writeHead(404);
    res.end();
  });
  const listening = Promise.withResolvers<void>();
  server.listen(0, '127.0.0.1', listening.resolve);
  await listening.promise;
  return {
    server,
    url: `http://127.0.0.1:${(server.address() as { port: number }).port}`,
  };
}

type FaEventRecord = { type: string; role?: string; text?: string; error?: unknown };

async function bootWith(fa: FaHarness, url: string): Promise<void> {
  await fa.swEval((cfg) => {
    const sw = globalThis as unknown as {
      faAgent: {
        boot(config: Record<string, unknown>): Promise<{ ok: boolean }>;
      };
    };
    return sw.faAgent.boot(cfg);
  }, {
    approvalMode: 'unattended',
    provider: { baseUrl: url, apiKey: '[REDACTED:Sensitive Value]', model: 'slow' },
  });
}

function isUserDone(e: FaEventRecord, needle: string): boolean {
  return e.type === 'message_done' && e.role === 'user'
    && String(e.text).includes(needle);
}

async function waitForAssistantCount(
  fa: FaHarness,
  count: number,
  after: number,
): Promise<void> {
  await expect.poll(async () => {
    const events = await fa.events();
    return events
      .slice(after + 1)
      .filter((e) => (e as FaEventRecord).type === 'message_done'
        && (e as FaEventRecord).role === 'assistant').length;
  }, { timeout: 60_000 }).toBe(count);
}

async function expectNoAborts(fa: FaHarness, after: number): Promise<void> {
  const events = await fa.events();
  const aborted = events
    .slice(after + 1)
    .filter((e) => String((e as FaEventRecord).error ?? '')
      .toLowerCase()
      .includes('abort'));
  expect(aborted, `aborted surfaced: ${JSON.stringify(aborted)}`).toHaveLength(0);
}

async function closeServer(server: http.Server): Promise<void> {
  const closed = Promise.withResolvers<void>();
  server.close(() => closed.resolve());
  await closed.promise;
}

test.describe('steering a streaming run (#314)', () => {
  skipWithoutChrome();

  test('E2E-steer: composer steering mid-stream lands at the boundary, '
      + 'the run never surfaces an aborted error', async ({ fa }) => {
        const { server, url } = await startSlowSseServer();
        try {
          await bootWith(fa, url);
          await fa.collectEvents();
          const before = (await fa.eventCount()) - 1;

          await fa.sendUser('hello there');
          // The reply is streaming…
          await fa.waitEvent(
            (e) => e.type === 'delta' && String(e.text).includes('d1'),
            30_000,
            before,
          );
          // …steer through the same seam the panel composer rides while
          // the agent is running.
          await fa.sendUser('STEER-NOW please continue');

          // …the surface immediately gets the neutral steer_queued event.
          const queued = await fa.waitEvent(
            (e) => e.type === 'steer_queued' && String(e.text).includes('STEER-NOW'),
            10_000,
            before,
          );
          expect(queued).toBeTruthy();

          // The first reply runs to NATURAL completion — all 8 deltas, a
          // message_done with no error.
          const firstDone = await fa.waitEvent(
            (e) =>
              e.type === 'message_done' &&
              e.role === 'assistant' &&
              String(e.text).includes('d8'),
            30_000,
            before,
          );
          expect(
            firstDone.error,
            `first reply must not error: ${JSON.stringify(firstDone)}`,
          ).toBeUndefined();

          // The steering is delivered as the next step's user message…
          const steered = await fa.waitEvent(
            (e) =>
              e.type === 'message_done' &&
              e.role === 'user' &&
              String(e.text).includes('STEER-NOW'),
            30_000,
            before,
          );
          expect(steered).toBeTruthy();

          // …and its own reply follows (a second assistant message_done).
          const secondDone = await fa.waitEvent(
            (e) =>
              e.type === 'message_done' &&
              e.role === 'assistant',
            30_000,
            before + 1,
          );
          expect(secondDone).toBeTruthy();

          // NO aborted text anywhere on the surface.
          const events = await fa.events();
          const aborted = events
            .slice(before + 1)
            .filter((e) =>
              String((e as { error?: unknown }).error ?? '')
                .toLowerCase()
                .includes('abort'),
            );
          expect(
            aborted,
            `aborted surfaced: ${JSON.stringify(aborted)}`,
          ).toHaveLength(0);
        } finally {
          await new Promise<void>((r) => server.close(() => r()));
        }
      }, 120_000);
});

test.describe('steering edge semantics (#314)', () => {
  skipWithoutChrome();

  test('E2E-steer-multi: several steers during one stream queue in order '
      + 'and land one per boundary', async ({ fa }) => {
        const { server, url } = await startSlowSseServer();
        try {
          await bootWith(fa, url);
          await fa.collectEvents();
          const before = (await fa.eventCount()) - 1;

          await fa.sendUser('hello there');
          await fa.waitEvent(
            (e) => e.type === 'delta' && String(e.text).includes('d1'),
            30_000,
            before,
          );
          await fa.sendUser('STEER-ONE');
          await fa.sendUser('STEER-TWO');

          // Both steered messages land as user steps, in order…
          const first = await fa.waitEvent(
            (e) => isUserDone(e, 'STEER-ONE'),
            45_000,
            before,
          );
          const second = await fa.waitEvent(
            (e) => isUserDone(e, 'STEER-TWO'),
            45_000,
            before,
          );
          expect(first).toBeTruthy();
          expect(second).toBeTruthy();

          // …and every steered step got its own reply (3 assistants total).
          await waitForAssistantCount(fa, 3, before);
          await expectNoAborts(fa, before);
        } finally {
          await closeServer(server);
        }
      }, 180_000);

  test('E2E-steer-mail: bridge mail during a stream steers the run '
      + 'instead of aborting it', async ({ fa }) => {
        const { server, url } = await startSlowSseServer();
        try {
          await bootWith(fa, url);
          await fa.collectEvents();
          const before = (await fa.eventCount()) - 1;

          await fa.sendUser('hello there');
          await fa.waitEvent(
            (e) => e.type === 'delta' && String(e.text).includes('d1'),
            30_000,
            before,
          );
          await fa.swEval(() => {
            const sw = globalThis as unknown as {
              faAgent: {
                pushMail(from: string, text: string): void;
              };
            };
            sw.faAgent.pushMail('peer', 'mail steering mid-stream');
          });

          const steered = await fa.waitEvent(
            (e) => isUserDone(e, '[from peer] mail steering mid-stream'),
            45_000,
            before,
          );
          expect(steered).toBeTruthy();
          await expectNoAborts(fa, before);
        } finally {
          await closeServer(server);
        }
      }, 120_000);

  test('E2E-steer-indicator: the panel shows a neutral pending marker the '
      + 'moment a steer is queued, cleared when the message lands', async ({ fa }) => {
        // This test drives the legacy fallback composer (#prompt,
        // #sendPrompt, .bubble.steer). With an app bundle the panel
        // redirects to the Flutter app and those selectors never render
        // (gh-1521) — same convention as panel-focus/paste. The app
        // branch's steer indicator is covered by the relay unit tests.
        test.skip(
          appBundlePresent,
          'legacy composer only — the app build redirects the panel to app/',
        );
        const { server, url } = await startSlowSseServer();
        try {
          await bootWith(fa, url);
          // Drive the REAL composer UI: no collectEvents here, so the
          // sw/main.js panel fan-out listener stays armed.
          await fa.panel.fill('#prompt', 'hello there');
          await fa.panel.click('#sendPrompt');
          await fa.panel
            .waitForSelector('.bubble.assistant', { timeout: 30_000 });

          await fa.panel.fill('#prompt', 'STEER-VIA-PANEL');
          await fa.panel.click('#sendPrompt');
          const marker = await fa.panel.waitForSelector('.bubble.steer', {
            timeout: 10_000,
          });
          expect(marker).toBeTruthy();

          // The steered message lands at the boundary: its user bubble…
          await fa.panel.waitForFunction(
            () => [...document.querySelectorAll('.bubble.user')]
              .some((b) => b.textContent?.includes('STEER-VIA-PANEL')),
            { timeout: 45_000 },
          );
          // …consumes the marker…
          await expect
            .poll(() => fa.panel.$$('.bubble.steer').then((r) => r.length))
            .toBe(0);
          // …and no aborted error ever hit the panel log.
          const logText = await fa.panel.evaluate(
            () => document.querySelector('#log')?.textContent ?? '',
          );
          expect(logText.toLowerCase()).not.toContain('abort');
        } finally {
          await closeServer(server);
        }
      }, 120_000);
});

