          const firstDone = await fa.waitEvent(
            (e) =>
              e.type === 'message_done' &&
              e.role === 'assistant' &&
              String(e.text).includes('d8'),
            30_000,
            before,
          );
          expect(
            firstDone.error,
            `first reply must not error: ${JSON.stringify(firstDone)}`,
          ).toBeUndefined();

